// Trust boundary: the chatbot is ours, but validate anyway.
const b = $json.body || {};
const business = String(b.business || '');
if (!['clinic', 'restaurant', 'agency', 'hotel'].includes(business)) throw new Error('Unknown business: ' + business);
const s = (v, max) => String(v ?? '').trim().slice(0, max);
const out = { business, name: s(b.name, 100), phone: s(b.phone, 30), when: s(b.when, 100), details: s(b.details, 500) };
if (!out.name || !out.phone || !out.when) throw new Error('Chatbot request missing name, phone or when');
return { json: out };

