// Turn the AI reading into one sheet row + one Telegram alert, shaped per business.
const req = $('Check request').item.json;
let ai = {};
try { ai = JSON.parse($json.candidates?.[0]?.content?.parts?.[0]?.text ?? ''); } catch (e) {}
const g = k => (typeof ai[k] === 'string' ? ai[k].trim() : '');
const isDate = v => /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : '';
const isTime = v => /^([01]\d|2[0-3]):[0-5]\d$/.test(v) ? v : '';
const date = isDate(g('date')), time = isTime(g('time'));
const priority = ['low', 'normal', 'high'].includes(ai.priority) ? ai.priority : 'normal';
// AI failed -> keep the raw text so staff still see everything
const summary = g('summary') || `AI could not read this request. When: ${req.when}. Details: ${req.details || '-'}`;
const language = ai.language === 'ar' || (!ai.language && /[؀-ۿ]/.test(req.name + req.details)) ? 'ar' : 'en';
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const stamp = $now.toFormat('yyMMdd-HHmmss');
const when = date ? `${date}${time ? ' at ' + time : ''}` : `${req.when} (date not understood)`;
const base = `Name: ${req.name}\nPhone: ${req.phone}`;
const tail = `\nNote: ${summary}\nVia: website chatbot`;
let tab, row, alert;

if (req.business === 'clinic') {
  tab = 'Bookings';
  row = { id: 'BK-' + stamp, created_at: now, name: req.name, phone: req.phone, email: '', date, time,
          status: 'Pending', reminder_sent: 'false', language, summary: '[Chatbot] ' + summary };
  alert = (priority === 'high' ? '🚨 URGENT – patient in pain (chatbot)\n\n' : '🦷 New booking request (chatbot)\n\n')
    + `Ref: ${row.id}\n${base}\nWhen: ${when}\nReason: ${g('reason') || '-'}${tail}\n\nStatus: Pending – call to confirm, then set Confirmed in Bookings.`;
} else if (req.business === 'restaurant') {
  tab = 'Reservations';
  const guests = g('guests'), allergies = g('allergies');
  row = { id: 'RS-' + stamp, created_at: now, name: req.name, phone: req.phone, date, time, guests,
          allergies, occasion: g('occasion'), status: 'Pending', language, summary };
  alert = `🍽 New table request\n\nRef: ${row.id}\n${base}\nWhen: ${when}\nGuests: ${guests || '?'}`
    + (Number(guests) >= 8 ? '  👥 large party' : '')
    + (allergies ? `\n⚠️ ALLERGY: ${allergies} – kitchen must confirm` : '')
    + (row.occasion ? `\n🎉 Occasion: ${row.occasion}` : '') + tail + '\n\nText the guest to confirm within 2 hours.';
} else if (req.business === 'agency') {
  tab = 'Leads';
  const score = { high: 'Hot', normal: 'Warm', low: 'Cold' }[priority];
  row = { id: 'LD-' + stamp, created_at: now, name: req.name, phone: req.phone, company: g('company'), need: g('need'),
          budget: g('budget'), call_date: date, call_time: time, score, status: 'New', summary };
  alert = `${{ Hot: '🔥', Warm: '🟡', Cold: '⚪' }[score]} ${score} lead – strategy call\n\nRef: ${row.id}\n${base}`
    + `\nBusiness: ${row.company || '-'}\nWants: ${row.need || '-'}\nBudget: ${row.budget || 'not shared'}\nCall: ${when}${tail}`;
} else {
  tab = 'Stays';
  const out = isDate(g('end_date'));
  const nights = date && out ? Math.max(0, Math.round((new Date(out) - new Date(date)) / 864e5)) : '';
  const daysAway = date ? Math.round((new Date(date) - new Date($now.toFormat('yyyy-MM-dd'))) / 864e5) : null;
  row = { id: 'ST-' + stamp, created_at: now, name: req.name, phone: req.phone, check_in: date, check_out: out,
          nights: String(nights), guests: g('guests'), room: g('room'), extras: g('extras'), status: 'Pending', language, summary };
  alert = `🏨 New stay request\n\nRef: ${row.id}\n${base}\nDates: ${date || req.when} → ${out || '?'}${nights !== '' ? ` (${nights} night${nights === 1 ? '' : 's'})` : ''}`
    + `\nGuests: ${row.guests || '?'}\nRoom: ${row.room || 'not chosen'}`
    + (row.extras ? `\n🧳 Extras: ${row.extras}` : '')
    + (daysAway !== null && daysAway <= 3 ? `\n⏰ Arrives in ${daysAway} day(s) – check availability now` : '') + tail;
}
return { json: { ...row, _tab: tab, _alert: alert } };
